steps.script:
var sel = tree.root.get_node("/root/Main/HUD_Right/VBoxContainer/ChargeScrollContainer/ChargePanel/ChargeUnitSelector")
if sel.item_count == 0:
	return false
return "Boyz" in str(sel.get_item_text(0))

var tl = tree.root.get_node("/root/Main/HUD_Right/VBoxContainer/ChargeScrollContainer/ChargePanel/ChargeTargetList")
for i in range(tl.item_count):
	if "Custodian" in str(tl.get_item_text(i)):
		tl.select(i, true)
		tl.multi_selected.emit(i, true)
		return true
return false

var q = [tree.root]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is Button and nd.is_visible_in_tree() and str(nd.text).strip_edges() == "Keep Roll":
		nd.pressed.emit()
		return true
	for c in nd.get_children():
		q.append(c)
return false

var cc = tree.root.get_node_or_null("/root/Main/ChargeController")
if cc == null:
	return "no ChargeController"
return "U_WARBOSS_T:m1" in cc.moved_models

var cc = tree.root.get_node_or_null("/root/Main/ChargeController")
if cc == null:
	return "no ChargeController"
var cust = GameState.get_unit("U_CUSTODIAN_GUARD_T").get("models", [])
var offenders = []
for key in cc.moved_models:
	var m = cc._get_charge_group_model(key)
	var origin = cc._model_origin_positions.get(key, null)
	if m.is_empty() or origin == null:
		continue
	var dest = cc.moved_models[key]["position"]
	var test = m.duplicate()
	var hit = false
	for i in range(1, 40):
		test["position"] = origin.lerp(dest, float(i) / 40.0)
		for c in cust:
			if c.get("alive", true) and Measurement.models_overlap(test, c):
				hit = true
				break
		if hit:
			break
	if hit:
		offenders.append(key)
return ", ".join(offenders)
